parameters.jsCode:
// Assemble all items into a single context block for Claude
// Organized by category for better brief structure

const items = $input.all();

if (items.length === 0) {
  return [{ json: { _empty: true, message: 'No items found for this week' } }];
}

// Group by category
const grouped = {};
for (const item of items) {
  const cat = item.json.properties?.Category?.select?.name || item.json.ai_category || 'uncategorized';
  if (!grouped[cat]) grouped[cat] = [];
  grouped[cat].push({
    title: item.json.properties?.Name?.title?.[0]?.text?.content || item.json.title || 'Untitled',
    source: item.json.properties?.Source?.select?.name || item.json.source || 'Unknown',
    score: item.json.properties?.Score?.number || item.json.relevance_score || 0,
    angle: item.json.properties?.['Newsletter Angle']?.rich_text?.[0]?.text?.content || item.json.newsletter_angle || '',
    tier: item.json.properties?.['Newsletter Tier']?.select?.name || item.json.newsletter_tier || 'all',
    url: item.json.properties?.URL?.url || item.json.url || ''
  });
}

// Format for Claude prompt
let context = `RESEARCH ITEMS THIS WEEK (${items.length} total):\n\n`;

for (const [category, categoryItems] of Object.entries(grouped)) {
  context += `## ${category.toUpperCase()} (${categoryItems.length} items)\n`;
  for (const item of categoryItems) {
    context += `- [Score: ${item.score}] ${item.title} (${item.source})\n`;
    context += `  Angle: ${item.angle}\n`;
    context += `  Tier: ${item.tier}\n`;
    context += `  URL: ${item.url}\n\n`;
  }
}

return [{
  json: {
    item_count: items.length,
    categories: Object.keys(grouped),
    context_block: context,
    week_of: new Date().toISOString().split('T')[0]
  }
}];

// Parse Claude response and extract the newsletter draft

const response = $input.first().json;
let draft = '';

try {
  if (response.content && response.content[0] && response.content[0].text) {
    draft = response.content[0].text;
  }
} catch (e) {
  draft = 'ERROR: Could not parse Claude response. Check execution log.';
}

const weekOf = $('Assemble Context').first().json.week_of;
const itemCount = $('Assemble Context').first().json.item_count;

return [{
  json: {
    title: `The Prompt — Week of ${weekOf}`,
    draft_content: draft,
    item_count: itemCount,
    generated_at: new Date().toISOString(),
    status: 'draft',
    word_count: draft.split(/\s+/).length
  }
}];

