// Mark all processed items as 'reviewed' in Notion
// This prevents them from being included in next week's brief

const items = $('Fetch Week Items').all();
const pageIds = items.map(i => i.json.id).filter(Boolean);

return pageIds.map(id => ({ json: { pageId: id, status: 'used' } }));

